'use strict';
window.Vocabulary=(()=>{
 function normalize(list){if(!Array.isArray(list))return [];const seen=new Set();return list.filter(w=>w&&typeof w.id==='string'&&/^custom:[a-zA-Z0-9-]{1,100}$/.test(w.id)&&!seen.has(w.id)&&seen.add(w.id)&&typeof w.korean==='string'&&w.korean.trim()&&typeof w.answer==='string'&&w.answer.trim()&&Number.isInteger(w.studyRef?.chapter)&&w.studyRef.chapter>=1&&w.studyRef.chapter<=15&&window.StudyEngine.validDate(w.studyRef?.date)).slice(0,5000).map(w=>({...make(w.id,w.korean.slice(0,160),w.answer.slice(0,1500),w.studyRef.chapter,w.studyRef.part||'vocabulary-1',w.studyRef.date,w.translationSource||'manual'),deleted:w.deleted===true,addedAt:typeof w.addedAt==='string'?w.addedAt:'',forms:[...new Set([w.korean,...(Array.isArray(w.forms)?w.forms.filter(f=>typeof f==='string'&&f.trim()).map(f=>f.slice(0,160)).slice(0,30):[])])],note:typeof w.note==='string'?w.note.slice(0,3000):'',pronunciation:typeof w.pronunciation==='string'?w.pronunciation.slice(0,160):w.korean}))}
 function make(id,korean,meaning,chapter,part,date,translationSource){return{id,custom:true,korean,forms:[korean],answer:meaning,quizAnswer:meaning,note:'',categories:['Book notes','Book vocabulary','Book chapter '+chapter,'Book day '+date],sourcePages:[],occurrences:[],count:1,important:false,learned:false,translationSource,studyRef:{chapter,part,date,kind:'vocabulary',lesson:'custom-'+date+'-ch'+chapter},pronunciation:korean}}
 async function translate(korean,target='en',fetcher=fetch){const url=new URL('https://api.mymemory.translated.net/get');url.searchParams.set('q',korean);url.searchParams.set('langpair','ko|'+target);if(new TextEncoder().encode(korean).length>500)throw Error('Use a shorter word or phrase.');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const r=await fetcher(url.toString(),{signal:controller.signal});if(!r.ok)throw Error('Translation service is unavailable. You can enter the meaning yourself.');const data=await r.json(),meaning=data.responseData?.translatedText;if(+data.responseStatus!==200||typeof meaning!=='string'||!meaning.trim()||data.quotaFinished)throw Error('Translation limit or service error. Enter the meaning yourself.');return meaning.trim()}finally{clearTimeout(timeout)}}
 function sync(){words=[...words.filter(w=>!w.custom),...state.customWords.filter(w=>!w.deleted)];window.StudyViews?.index(words)}
 function add(korean,meaning,chapter,part,date,translationSource='manual',topicId='general'){if(!korean.trim()||!meaning.trim())throw Error('Korean and meaning are required.');const list=state.customWords||[],existing=list.find(w=>!w.deleted&&w.korean===korean.trim()&&w.studyRef.chapter===chapter&&w.studyRef.date===date);const card=make(existing?.id||'custom:'+crypto.randomUUID(),korean.trim(),meaning.trim(),chapter,part,date,translationSource);card.addedAt=existing?.addedAt||new Date().toISOString();state.customWords=existing?list.map(w=>w.id===existing.id?card:w):[...list,card];sync();window.VocabularyHub?.assign(card.id,topicId);state.curriculum.reviews[card.id]||={due:window.StudyEngine.addDays(date,1),interval:0,successes:0,lapses:0,lastDate:'',lastResult:false};if(date===today()){const s=state.curriculum.sessions[date]||{minutes:0,tasks:[],note:''};s.tasks=[...new Set([...s.tasks,'add-vocabulary'])];state.curriculum.sessions[date]=s}save();return card}
 function update(id,korean,meaning){const old=state.customWords.find(w=>w.id===id);if(!old)return; if(!korean.trim()||!meaning.trim())throw Error('Korean and meaning are required.');const card={...make(id,korean.trim().slice(0,160),meaning.trim().slice(0,1500),old.studyRef.chapter,old.studyRef.part,old.studyRef.date,'manual correction'),deleted:old.deleted===true,addedAt:old.addedAt||'',note:old.note||'',forms:korean.trim()===old.korean?old.forms:[korean.trim().slice(0,160)]};state.customWords=state.customWords.map(w=>w.id===id?card:w);sync();save();return card}
 function remove(id,deleted=true){const word=state.customWords.find(w=>w.id===id);if(!word)return;word.deleted=deleted;sync();save();return word}
 function edit(id){const returnView=window.StudyHub.currentView?.()==='vocabulary'?'vocabulary':'notes';const w=words.find(w=>w.id===id);if(!w?.custom)return;showDialog(`<h2>Edit word</h2><label class="session-field">Korean<input id="editCustomKorean" lang="ko" maxlength="160" value="${e(w.korean)}"></label><label class="session-field">Meaning<textarea id="editCustomMeaning" maxlength="1500">${e(w.answer)}</textarea></label><div class="hub-actions"><button class="btn primary" id="saveCustomMeaning">Save changes</button><button class="btn danger" id="deleteCustomWord">Delete word</button></div><p id="editWordError" role="status"></p>`);$('#saveCustomMeaning').onclick=()=>{try{update(id,$('#editCustomKorean').value,$('#editCustomMeaning').value);$('#dialog').close();window.StudyHub.open(returnView)}catch(err){$('#editWordError').textContent=err.message}};$('#deleteCustomWord').onclick=()=>{remove(id);$('#dialog').close();window.StudyHub.open(returnView);toast('Word deleted. You can restore it from Deleted words.')}}
 function form(chapter=1,options={}){return`<form id="vocabularyForm" class="vocabulary-form"><div class="planner-options"><label for="newEntryKind">Entry type<select id="newEntryKind"><option value="vocabulary">Vocabulary</option><option value="grammar">Grammar structure</option><option value="rule">Rule</option></select></label><label for="newWordTopic" id="newTopicField">Category<select id="newWordTopic">${window.VocabularyHub?.options(options.topic||'general')||'<option value="general">General</option>'}</select></label><label for="newWordChapter">Save to chapter<select id="newWordChapter">${Array.from({length:15},(_,i)=>`<option value="${i+1}" ${chapter===i+1?'selected':''}>Chapter ${i+1}</option>`).join('')}</select></label><label for="newWordPart">Lesson<select id="newWordPart">${[1,2,3].map(n=>`<option value="vocabulary-${n}" ${options.part==='vocabulary-'+n?'selected':''}>Grammar ${n} lesson</option>`).join('')}<option value="extra" ${options.part==='extra'?'selected':''}>Other chapter words</option></select></label><label for="newWordDate">Study day<input type="date" id="newWordDate" value="${e(options.date||today())}"></label><label for="newWordLanguage">Translate into<select id="newWordLanguage"><option value="en">English</option><option value="ru" ${options.target==='ru'?'selected':''}>Russian</option></select></label></div><label for="newKorean">Korean word, structure or rule title<input id="newKorean" lang="ko" maxlength="160" placeholder="Type Korean, then press Enter" required autocomplete="off"></label><label for="newMeaning">Meaning · optional override<textarea id="newMeaning" rows="2" maxlength="1500" placeholder="Leave blank for automatic translation"></textarea></label><button class="btn primary" id="translateSave" type="submit">Translate & save card →</button><p class="quiet">Automatic translation: MyMemory. Only the Korean text is sent. You can edit the result.</p><p id="translationStatus" role="status"></p><div id="newWordResult"></div></form>`}
 function bind({onSaved}={}){let busy=false;const kindSelect=$('#newEntryKind');if(kindSelect)kindSelect.onchange=()=>{$('#newTopicField').hidden=kindSelect.value!=='vocabulary';$('#newMeaning').required=kindSelect.value!=='vocabulary';$('#newMeaning').placeholder=kindSelect.value==='vocabulary'?'Leave blank for automatic translation':'Add an explanation or examples';$('#translateSave').textContent=kindSelect.value==='vocabulary'?'Translate & save card →':'Save entry'};$('#vocabularyForm').onsubmit=async ev=>{ev.preventDefault();if(busy)return;const korean=$('#newKorean').value.trim(),manual=$('#newMeaning').value.trim(),chapter=+$('#newWordChapter').value,part=$('#newWordPart').value,date=$('#newWordDate').value,target=$('#newWordLanguage').value,kind=$('#newEntryKind')?.value||'vocabulary';if(kind!=='vocabulary'&&!manual){$('#translationStatus').textContent='Add an explanation or examples';return}if(!korean||!window.StudyEngine.validDate(date)||date>today()){$('#translationStatus').textContent='Enter Korean and a study date up to today.';return}busy=true;$('#translateSave').disabled=true;$('#translationStatus').textContent=manual?'Saving…':'Translating and saving…';try{const known=target==='en'&&words.find(w=>w.korean===korean&&!w.hanjaRef&&w.studyRef?.kind!=='grammar'&&!/[А-Яа-яЁё]/.test(w.quizAnswer)),meaning=manual||(known?.quizAnswer)||await translate(korean,target);let card;if(kind==='vocabulary')card=add(korean,meaning,chapter,part,date,manual?'manual':known?'existing study vocabulary':'MyMemory automatic',$('#newWordTopic')?.value||'general');else{const note=window.ReferenceNotes.add(kind,korean,meaning,{chapter,part,date});card={id:note.id,korean:note.title,answer:note.text};const session=state.curriculum.sessions[today()]||{minutes:0,tasks:[],note:''};session.tasks=[...new Set([...session.tasks,'add-vocabulary'])];state.curriculum.sessions[today()]=session;save()}if(typeof document!=='undefined'){const check=document.querySelector('[data-task="add-vocabulary"]');if(check){check.checked=true;check.closest('details')?.classList.add('is-done');const done=document.querySelectorAll('[data-task]:checked').length,bar=document.querySelector('.daily-heading progress'),count=document.querySelector('.daily-heading span');if(bar)bar.value=done;if(count)count.textContent=done+' / 5 completed'}}$('#translationStatus').textContent='Saved to Chapter '+chapter+' · '+date;$('#newWordResult').innerHTML=`<div class="saved-word"><strong>${e(card.korean)}</strong> → <span class="saved-meaning" translate="no">${e(card.answer)}</span> <button type="button" class="text-link" id="correctNewWord">Edit word</button></div>`;$('#correctNewWord').onclick=()=>{if(kind==='vocabulary')edit(card.id);else{window.StudyHub.open(kind==='rule'?'rules':'grammar');window.ReferenceNotes.edit(kind,card.id)}};$('#newKorean').value='';$('#newMeaning').value='';$('#newKorean').focus();onSaved?.({kind,card,chapter,part,date,target})}catch(error){$('#translationStatus').textContent=error.name==='AbortError'?'Translation timed out. Enter the meaning and save manually.':error.message}finally{busy=false;$('#translateSave').disabled=false}}}
 return{normalize,make,translate,sync,add,update,remove,edit,form,bind};
})();
